module bug_free_plans(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [3:0] m,\n    input wire [3:0] b,\n    input wire [31:0] mod,\n    input wire [8:0] a_0,\n    input wire [8:0] a_1,\n    input wire [8:0] a_2,\n    input wire [8:0] a_3,\n    input wire [8:0] a_4,\n    input wire [8:0] a_5,\n    input wire [8:0] a_6,\n    input wire [8:0] a_7,\n    output reg [31:0] result,\n    output reg done\n);\n\n    localparam MAX_M = 4'd8;\n    localparam MAX_B = 4'd8;\n\n    // State declarations\n    localparam [2:0] IDLE   = 3'd0;\n    localparam [2:0] INIT   = 3'd1;\n    localparam [2:0] FETCH_A = 3'd2;\n    localparam [2:0] UPDATE = 3'd3;\n    localparam [2:0] SUM    = 3'd4;\n    localparam [2:0] DONE   = 3'd5;\n\n    reg [2:0] state;\n    reg [3:0] i;           // Programmer index\n    reg [3:0] lines;       // Current line count\n    reg [3:0] bugs;        // Current bug count\n    reg [3:0] init_lines;  // DP init line counter\n    reg [3:0] init_bugs;   // DP init bug counter\n    reg [3:0] sum_bugs;    // Summation bug counter\n\n    // DP array: dp[lines][bugs]\n    reg [31:0] dp [0:MAX_M][0:MAX_B];\n\n    // Current a_i\n    reg [8:0] current_a;\n\n    // Combinational logic for sum_update\n    reg [31:0] sum_update;\n\n    // A_i multiplexer\n    always @(*) begin\n        case(i)\n            4'd0: current_a = a_0;\n            4'd1: current_a = a_1;\n            4'd2: current_a = a_2;\n            4'd3: current_a = a_3;\n            4'd4: current_a = a_4;\n            4'd5: current_a = a_5;\n            4'd6: current_a = a_6;\n            4'd7: current_a = a_7;\n            default: current_a = 9'd0;\n        endcase\n    end\n\n    // Sum update combinational logic\n    always @(*) begin\n        if (lines >= 4'd1 && bugs >= current_a && (bugs - current_a) <= MAX_B) begin\n            sum_update = dp[lines][bugs] + dp[lines-4'd1][bugs - current_a];\n            if (sum_update >= mod) sum_update = sum_update - mod;\n        end else begin\n            sum_update = dp[lines][bugs];\n        end\n    end\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            i <= 4'd0;\n            lines <= 4'd0;\n            bugs <= 4'd0;\n            init_lines <= 4'd0;\n            init_bugs <= 4'd0;\n            sum_bugs <= 4'd0;\n        end else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        init_lines <= 4'd0;\n                        init_bugs <= 4'd0;\n                    end\n                end\n\n                INIT: begin\n                    dp[init_lines][init_bugs] <= 32'd0;\n                    if (init_bugs == MAX_B) begin\n                        init_bugs <= 4'd0;\n                        if (init_lines == MAX_M) begin\n                            dp[4'd0][4'd0] <= 32'd1; // Base case\n                            state <= FETCH_A;\n                            i <= 4'd0;\n                        end else begin\n                            init_lines <= init_lines + 4'd1;\n                        end\n                    end else begin\n                        init_bugs <= init_bugs + 4'd1;\n                    end\n                end\n\n                FETCH_A: begin\n                    bugs <= 4'd0;\n                    lines <= 4'd0;\n                    if (i >= n) begin\n                        state <= SUM;\n                        sum_bugs <= 4'd0;\n                        result <= 32'd0;\n                    end else begin\n                        if (current_a > b || m == 4'd0) begin\n                            i <= i + 4'd1;\n                        end else begin\n                            lines <= 4'd1;\n                            bugs <= current_a;\n                            state <= UPDATE;\n                        end\n                    end\n                end\n\n                UPDATE: begin\n                    if (bugs <= b) begin\n                        dp[lines][bugs] <= sum_update;\n                    end\n\n                    if (bugs == b) begin\n                        bugs <= current_a;\n                        if (lines == m) begin\n                            i <= i + 4'd1;\n                            state <= FETCH_A;\n                        end else begin\n                            lines <= lines + 4'd1;\n                        end\n                    end else begin\n                        bugs <= bugs + 4'd1;\n                    end\n                end\n\n                SUM: begin\n                    if (sum_bugs <= b) begin\n                        result <= (result + dp[m][sum_bugs]) % mod;\n                    end\n\n                    if (sum_bugs == b) begin\n                        state <= DONE;\n                        done <= 1'b1;\n                        sum_bugs <= 4'd0;\n                    end else begin\n                        sum_bugs <= sum_bugs + 4'd1;\n                    end\n                end\n\n                DONE: begin\n                    state <= IDLE;\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule